class _StreamlitFalso:
    """Registra as chamadas de `render()` sem Streamlit instalado: pega erro de nome/fluxo da tela."""

    def __init__(self):
        self.session_state, self.chamadas = {}, []

    def _widget(self, nome):
        def chamar(*args, **kwargs):
            self.chamadas.append((nome, args, kwargs))
            if nome == "text_input":
                return args[1]
            if nome == "selectbox":
                return list(args[1])[0] if list(args[1]) else None
            if nome == "button":
                return True
            if nome in ("tabs", "columns"):
                n = args[0] if isinstance(args[0], int) else len(args[0])
                return [self for _ in range(n)]
            return self
        return chamar

    def __getattr__(self, nome):
        return self._widget(nome)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False


@pytest.mark.skipif(not PACK.exists(), reason="data pack ausente")
def test_render_percorre_todas_as_telas(tmp_path, monkeypatch):
    falso = _StreamlitFalso()
    monkeypatch.setitem(__import__("sys").modules, "streamlit", falso)
    monkeypatch.setattr(app, "RAIZ", app.RAIZ)  # entrada padrão = data pack do repositório
    monkeypatch.setattr(app, "competencia_padrao", lambda: "2026-09")
    real = app.executar
    monkeypatch.setattr(app, "executar", lambda e, c, s: real(e, c, str(tmp_path)))
    monkeypatch.setattr(app, "ler_saida", lambda pasta: app.__dict__["_ler"](tmp_path))
    app.__dict__["_ler"] = app.ler_saida.__wrapped__ if hasattr(app.ler_saida, "__wrapped__") else None
